def _raises(fn, exc=Exception):
    try:
        fn()
    except exc:
        return True
    except Exception:
        return False
    return False

def _boom():
    raise ConnectionError("policy service down")
_CALLS = []
def _tripped():
    c = FakeClock()
    b = CircuitBreaker(3, 30, c)
    for _ in range(3):
        _raises(lambda: b.call(_boom))
    return c, b
def _fail_fast():
    c, b = _tripped()
    def counted():
        _CALLS.append(1)
        return "x"
    blocked = _raises(lambda: b.call(counted), CircuitOpen)
    return blocked and not _CALLS
def _reset_by_success():
    b = CircuitBreaker(3, 30, FakeClock())
    _raises(lambda: b.call(_boom)); _raises(lambda: b.call(_boom))
    b.call(lambda: 1)
    _raises(lambda: b.call(_boom)); _raises(lambda: b.call(_boom))
    return b.state
def _recover():
    c, b = _tripped()
    c.tick(30)
    return b.call(lambda: "back"), b.state
def _failed_trial():
    c, b = _tripped()
    c.tick(31)
    _raises(lambda: b.call(_boom))
    state = b.state
    c.tick(29)
    still_blocked = _raises(lambda: b.call(lambda: 1), CircuitOpen)
    c.tick(1)
    return state, still_blocked, b.call(lambda: "ok") == "ok"
